-- IDENTITY.sql — the shared identity views MinusX reads (contracts IDENTITY_VIEWS,
-- cross-repository contract §2). Generated by scripts/render-schema.mjs (npm run
-- render:schema) from lib/groups identity-views; never edit by hand. These are
-- exactly the statements a combined-mode boot runs (server.ts), app tables on the
-- app's search_path and the auth schema named; MinusX's tests apply a byte-for-byte
-- copy of this file, so a change here is a change on both sides.
--
-- The grant an operator gives MinusX's database role (any name), after the boot
-- that creates the views, and nothing on any other Artifactbin schema or table:
--
--   GRANT USAGE ON SCHEMA identity TO <minusx role>;
--   GRANT SELECT ON ALL TABLES IN SCHEMA identity TO <minusx role>;

CREATE SCHEMA IF NOT EXISTS identity;

CREATE OR REPLACE VIEW identity.groups AS
  SELECT g.id, g.handle, g.name, g.parent_id FROM groups g WHERE g.deleted_at IS NULL;

CREATE OR REPLACE VIEW identity.memberships AS
  SELECT m.group_id, m.user_id FROM group_members m JOIN groups g ON g.id = m.group_id WHERE g.deleted_at IS NULL;

CREATE OR REPLACE VIEW identity.hierarchy AS
  SELECT h.revision FROM group_hierarchy h WHERE h.id = 'installation';

CREATE OR REPLACE VIEW identity.users AS
  SELECT u.id, (((u.kind='account' AND u.email IS NOT NULL) OR (u.kind = 'testuser' AND (u.expires_at IS NULL OR u.expires_at > now()) AND EXISTS
  (SELECT 1 FROM users parent WHERE parent.id = u.parent_user_id AND parent.kind = 'account' AND parent.email IS NOT NULL)))
    AND (s.deployment_mode = 'public' OR (EXISTS (SELECT 1 FROM deployment_members dm WHERE dm.user_id=u.id)
  OR EXISTS (SELECT 1 FROM users tu JOIN deployment_members pm ON pm.user_id=tu.parent_user_id JOIN deployment_state ds ON ds.id='company' AND ds.setup_complete=true
   WHERE tu.id=u.id AND (tu.kind = 'testuser' AND (tu.expires_at IS NULL OR tu.expires_at > now()) AND EXISTS
  (SELECT 1 FROM users parent WHERE parent.id = tu.parent_user_id AND parent.kind = 'account' AND parent.email IS NOT NULL)))))) AS active
  FROM users u JOIN identity_settings s ON s.id = 'installation';

CREATE OR REPLACE VIEW identity.sessions AS
  SELECT s.id, s."userId" AS user_id, (s."expiresAt" > now()) AS live FROM auth.session s;

CREATE OR REPLACE VIEW identity.tokens AS
  SELECT t.id, t.user_id, array_remove(regexp_split_to_array(coalesce(t.scope, ''), '\s+'), '') AS scopes,
    (t.deleted_at IS NULL AND (t.expires_at IS NULL OR t.expires_at>now())
      AND (COALESCE(t.audience,'')='' OR fence.live IS NOT NULL)
      AND t.user_id IS NOT NULL AND (COALESCE(t.audience,'') = '' OR t.audience = ANY(s.api_audiences))
      AND COALESCE(u.active, false)) AS live
  FROM tokens t
    LEFT JOIN LATERAL (
      SELECT 1 AS live FROM auth.credentials member
      JOIN auth.credentials family ON family.kind='refresh_family' AND family.credential_hash=member.group_id AND family.deleted_at IS NULL
      WHERE COALESCE(t.audience,'')<>'' AND member.kind='refresh_token' AND member.payload->>'access_token_id'=t.id
        AND NOT EXISTS (
          SELECT 1 FROM auth.credentials sibling LEFT JOIN tokens access ON access.id=sibling.payload->>'access_token_id'
          WHERE sibling.kind='refresh_token' AND sibling.group_id=member.group_id
            AND (sibling.deleted_at IS NOT NULL OR access.id IS NULL OR access.deleted_at IS NOT NULL))
      LIMIT 1
    ) fence ON true
    JOIN identity_settings s ON s.id = 'installation'
    LEFT JOIN identity.users u ON u.id = t.user_id;
